import SwiftUI
import UIKit

/// The two launcher icons the user can pick in Settings > Appearance.
///
/// `logo` is the primary icon (the car mark); `name` is the alternate
/// `AppIconWordmark` icon. Both are generated by `design/icons/make-icons.swift`.
enum HayameAppIcon: String, CaseIterable, Identifiable {
    case logo
    case name

    var id: String { rawValue }

    var title: String {
        switch self {
        case .logo: return "Logo"
        case .name: return "Name"
        }
    }

    var subtitle: String {
        switch self {
        case .logo: return "The Hayame car mark"
        case .name: return "The HAYAME wordmark"
        }
    }

    /// `nil` selects the primary icon.
    var alternateIconName: String? {
        switch self {
        case .logo: return nil
        case .name: return "AppIconWordmark"
        }
    }

    /// Asset-catalog preview used by the picker (the real icon is not readable at runtime).
    var previewImageName: String {
        switch self {
        case .logo: return "AppIconPreviewLogo"
        case .name: return "AppIconPreviewWordmark"
        }
    }

    static func from(alternateIconName: String?) -> HayameAppIcon {
        alternateIconName == HayameAppIcon.name.alternateIconName ? .name : .logo
    }
}

@MainActor
final class AppIconManager: ObservableObject {
    static let shared = AppIconManager()

    @Published private(set) var current: HayameAppIcon
    @Published private(set) var isChanging = false
    @Published var lastError: String?

    var supportsAlternateIcons: Bool {
        UIApplication.shared.supportsAlternateIcons
    }

    private init() {
        current = HayameAppIcon.from(alternateIconName: UIApplication.shared.alternateIconName)
    }

    func select(_ icon: HayameAppIcon) async {
        guard icon != current, !isChanging else { return }
        guard supportsAlternateIcons else {
            lastError = "This device can't change app icons."
            return
        }
        isChanging = true
        defer { isChanging = false }
        do {
            try await UIApplication.shared.setAlternateIconName(icon.alternateIconName)
            current = icon
            lastError = nil
            HayameHaptics.success()
        } catch {
            lastError = error.localizedDescription
            HayameHaptics.error()
        }
    }

    #if DEBUG
    /// `-HAYAME_APP_ICON name|logo` switches the icon shortly after launch so the
    /// alternate icon can be verified on a simulator without tapping through Settings.
    func applyLaunchArgumentIfNeeded() {
        let args = ProcessInfo.processInfo.arguments
        guard let index = args.firstIndex(of: "-HAYAME_APP_ICON"), args.indices.contains(index + 1),
              let icon = HayameAppIcon(rawValue: args[index + 1]) else { return }
        Task { @MainActor in
            try? await Task.sleep(nanoseconds: 1_000_000_000)
            await select(icon)
        }
    }
    #endif
}
